import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC-0006: Pi-hole Capability Mapping","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/0006-pihole-capability-mapping.md"},"headers":[],"relativePath":"sovereign-os/rfcs/0006-pihole-capability-mapping.md","filePath":"sovereign-os/rfcs/0006-pihole-capability-mapping.md"}'),n={name:"sovereign-os/rfcs/0006-pihole-capability-mapping.md"};function s(r,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="rfc-0006-pi-hole-capability-mapping" tabindex="-1">RFC-0006: Pi-hole Capability Mapping <a class="header-anchor" href="#rfc-0006-pi-hole-capability-mapping" aria-label="Permalink to &quot;RFC-0006: Pi-hole Capability Mapping&quot;">​</a></h1><p><strong>Status:</strong> Accepted (2026-08-09, project creator) <strong>Author:</strong> Project creator and Claude <strong>Created:</strong> 2026-08-09 <strong>Reviewers:</strong> Project creator <strong>Target phase:</strong> <a href="./../roadmap/01-2-local-conversation-capabilities.html">Milestone 01.2, Local Conversation and Capabilities</a><strong>Supersedes:</strong> None</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Register the specific read-only Pi-hole capabilities the milestone plan names, against <a href="./0003-capability-contract.html">RFC-0003</a>&#39;s contract and reachable through <a href="./0004-ai-capability-invocation.html">RFC-0004</a>&#39;s invocation path: <code>pihole.status</code> (is Pi-hole up, is blocking currently enabled) and <code>pihole.summary</code> (aggregate query/blocking counts for a bounded recent period). It fixes the household-privacy boundary these capabilities must respect — no per-domain, per-client, or query-log detail, only aggregate counts, matching the boundary Sovereign Console&#39;s own health page already established — and the credential-handling requirement for calling Pi-hole&#39;s real API rather than the coarse TCP reachability check Console currently uses. This RFC does not define mutating Pi-hole operations (explicit milestone non-scope) or generalize beyond Pi-hole to any other appliance service.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The milestone plan names &quot;read-only Pi-hole health and summary capabilities&quot; as one of four initial capabilities, and requires a &quot;Pi-hole capability mapping&quot; as its own required document (item 3 of 8). <a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a> was opened to investigate exactly this — endpoint-to-use-case mapping, authentication, sensitive-field minimization — but was never completed; its Status line still reads &quot;Planned&quot; with only the investigation questions written, not answers.</p><p>Separately, the only Pi-hole integration that exists today is <code>console-health</code>&#39;s check (<code>image-builder/sovereign/appliance/bin/console-health</code>): a bare TCP reachability check against Pi-hole&#39;s web port, chosen deliberately for Console&#39;s own narrow scope (&quot;Overall Healthy, Degraded, or Unavailable,&quot; explicitly not query history or per-client detail — see <a href="./../design/console-health.html">docs/design/console-health.md</a>&#39;s Non-Scope and Privacy and Trust sections). It does not call Pi-hole&#39;s real API at all, so it cannot answer &quot;how many queries were blocked today&quot; — the kind of question <code>pihole.summary</code> needs to answer. This RFC cannot reuse <code>console-health</code>&#39;s implementation, only its privacy boundary, which it explicitly carries forward.</p><p>Without this RFC, an implementation would have to decide, ad hoc, which Pi-hole data is safe to expose to a model-mediated capability — a much more consequential decision than Console&#39;s own health page, since a conversational interface invites the kind of specific question (&quot;what did my kid&#39;s phone look up today&quot;) that Console&#39;s glanceable health page never did, and that this household-facing product must refuse by design, not by omission.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Register <code>pihole.status</code> and <code>pihole.summary</code> against RFC-0003&#39;s contract: schema, classification, and bounds.</li><li>Fix the privacy boundary: aggregate counts only, no per-domain, per-client, or timestamped query-level detail, carried forward from <code>console-health</code>&#39;s own established Non-Scope rather than re-litigated.</li><li>Define how the capability implementation authenticates to Pi-hole&#39;s real API, and where that credential lives, without exposing it to the model or Conversation Service layer.</li><li>Name what remains for <code>pihole-api-assessment.md</code> to actually verify against the real, pinned Pi-hole version this device runs, rather than asserting unverified endpoint specifics as settled.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Any mutating Pi-hole capability (enable/disable blocking, add/remove blocklist entries, manage clients) — explicit milestone non-scope. This RFC&#39;s capabilities are exclusively <code>read_only</code>.</li><li>Per-domain or per-client query detail, query history, or anything resembling browsing-history reconstruction for a specific household member or device — never exposed through this capability surface, regardless of what Pi-hole&#39;s own admin API can technically return.</li><li><code>console-health</code>&#39;s existing Console-facing health check, which this RFC neither replaces nor depends on — they serve different consumers (an unauthenticated glanceable page vs. an authenticated conversation) with different, independently-justified scopes.</li><li>The general capability contract, executor pipeline, or AI invocation flow — fixed by RFC-0003 and RFC-0004; this RFC only supplies Pi-hole-specific schemas and data-handling rules.</li><li>Completing <code>pihole-api-assessment.md</code>&#39;s full investigation (exact endpoint paths verified against the real running version, full error taxonomy, rate-limit behavior). This RFC names what that research must still confirm before implementation; it does not replace the research.</li></ul><h2 id="context-and-evidence" tabindex="-1">Context and Evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to &quot;Context and Evidence&quot;">​</a></h2><ul><li><a href="./../design/console-health.html">docs/design/console-health.md</a> (Accepted) is the direct precedent for this RFC&#39;s privacy boundary: its Non-Scope (&quot;Logs, terminal, file browser, container details, or DNS query history&quot;) and Privacy and Trust section (&quot;must not expose... client identities, queries, logs, or browsing history&quot;) already establish, for a different surface, exactly the boundary this RFC needs for a conversational one — arguably a boundary that matters <em>more</em> here, since a conversation actively invites specific questions a glanceable status page never prompted.</li><li><code>image-builder/sovereign/appliance/bin/console-health</code> is the only existing Pi-hole integration: a TCP check on port 8080, no authenticated API call. Read directly to confirm this RFC is not duplicating or silently diverging from working code.</li><li><code>image-builder/sovereign/pihole-image.env</code> pins the actual Pi-hole image this device runs (<code>pihole/pihole:2026.04.1</code>, digest-verified) — this RFC&#39;s API assumptions must be checked against this specific pinned version, not Pi-hole in general, before implementation.</li><li><a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a> (Status: Planned, never completed) already scoped the right questions — authentication, health/summary endpoints, sensitive-field minimization, least-privilege credential support — this RFC answers them at the architecture level and names what still needs empirical confirmation.</li><li><a href="./0003-capability-contract.html">RFC-0003</a>&#39;s classification table and <a href="./0004-ai-capability-invocation.html">RFC-0004</a>&#39;s catalog-generation requirement are the contract these capabilities are registered against; this RFC supplies their <code>argument_schema</code>/<code>result_schema</code> and confirms their <code>side_effect</code>/<code>network</code> classification.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="pihole-status" tabindex="-1"><code>pihole.status</code> <a class="header-anchor" href="#pihole-status" aria-label="Permalink to &quot;\`pihole.status\`&quot;">​</a></h3><ul><li><strong>Purpose:</strong> answer &quot;is Pi-hole working&quot; and &quot;is blocking currently on&quot; — a conversational equivalent of Console&#39;s own health indicator, not a superset of it.</li><li><strong>Arguments:</strong> none.</li><li><strong>Result:</strong> <code>{ &quot;reachable&quot;: bool, &quot;blocking_enabled&quot;: bool | null, &quot;checked_at&quot;: timestamp }</code>. <code>blocking_enabled</code> is <code>null</code> if Pi-hole is unreachable — the capability reports what it actually observed, never guesses a default.</li><li><strong>Classification:</strong> <code>read_only</code>, <code>local</code> (the call stays inside the device, container-to-container; it never leaves the household network boundary the way <code>web.search</code> does), <code>automatic</code> confirmation per RFC-0003&#39;s structural table.</li><li><strong>Bounds:</strong> short timeout (matching <code>console-health</code>&#39;s existing responsiveness expectations), single result, no pagination.</li></ul><h3 id="pihole-summary" tabindex="-1"><code>pihole.summary</code> <a class="header-anchor" href="#pihole-summary" aria-label="Permalink to &quot;\`pihole.summary\`&quot;">​</a></h3><ul><li><strong>Purpose:</strong> answer aggregate questions — &quot;how many things got blocked today,&quot; &quot;is the blocklist working&quot; — without ever answering &quot;what did device X look up.&quot;</li><li><strong>Arguments:</strong> <code>{ &quot;period&quot;: &quot;today&quot; | &quot;last_24h&quot; }</code>. No arbitrary date range and no client or domain filter — a bounded, enumerated argument set is itself part of the privacy boundary, not just documentation of intent, since RFC-0003&#39;s argument-schema validation rejects anything outside it before the capability implementation ever runs.</li><li><strong>Result:</strong> <code>{ &quot;period&quot;: &quot;today&quot; | &quot;last_24h&quot;, &quot;queries_total&quot;: int, &quot;queries_blocked&quot;: int, &quot;blocked_percentage&quot;: number, &quot;blocklist_size&quot;: int, &quot;unique_clients&quot;: int, &quot;checked_at&quot;: timestamp }</code>. <code>unique_clients</code> is a count only — never a list of identities, addresses, or hostnames.</li><li><strong>Classification:</strong> <code>read_only</code>, <code>local</code>, <code>automatic</code>.</li><li><strong>Bounds:</strong> short timeout, single result, no pagination — this is a summary endpoint by design, not a query-log export.</li></ul><p>No other Pi-hole fields — domain lists, client identities, per-query timestamps, upstream DNS server detail beyond what&#39;s needed to report <code>reachable</code> — are exposed through either capability&#39;s result schema. RFC-0003&#39;s argument/result schema validation is what actually enforces this: a capability implementation cannot return a field the registered <code>result_schema</code> doesn&#39;t declare, so this boundary is structural, the same way RFC-0003 made confirmation structural rather than a per-author judgment call.</p><h3 id="authentication-and-credential-handling" tabindex="-1">Authentication and Credential Handling <a class="header-anchor" href="#authentication-and-credential-handling" aria-label="Permalink to &quot;Authentication and Credential Handling&quot;">​</a></h3><p>Pi-hole&#39;s real API (as opposed to <code>console-health</code>&#39;s bare TCP check) requires authenticating a session before reading stats — confirmed live against the real device in <a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a> (Concluded 2026-08-09): <code>POST /api/auth</code> with the admin password returns a session ID valid 30 minutes, extended by activity, presented on subsequent requests via an <code>sid</code> header. <strong>No least-privilege or read-only credential exists on this Pi-hole version</strong> — its only alternative to the full admin password is an &quot;application password&quot; that carries the same full authority and invalidates every other active session when generated. This is now a confirmed fact, not an open question: the credential this capability uses:</p><ul><li><strong>is the existing Pi-hole administrator password, reused</strong> — the only option, not a fallback among alternatives, per the research above;</li><li>is provisioned and stored under <code>/data/sovereign/secrets</code>, inside the same persistent-data boundary and backup role the appliance&#39;s other secrets already use — the same secret <code>sudo sovereign-pihole-password</code> already manages, not a new, separately-tracked credential store;</li><li>is readable only by the <code>pihole.status</code>/<code>pihole.summary</code> capability implementation process, never by the Conversation Service generally, the Inference Provider Adapter, or the model — matching RFC-0003&#39;s &quot;no ambient access beyond what implementation needs&quot; execution requirement; this is the boundary that actually bounds the risk of reusing a full-authority credential, since nothing in the conversation path can reach it even though the credential itself is not scope- limited;</li><li>should authenticate once and reuse/refresh a single long-lived session across invocations rather than authenticating fresh per call, per the research above&#39;s session/seat-limit findings — authenticating per invocation would needlessly compete with a household member&#39;s own concurrent Pi-hole web-UI login for Pi-hole&#39;s real, confirmed concurrent-session cap; and</li><li>is never logged, audited, or included in any capability result — RFC-0003&#39;s audit events already exclude result content, and this RFC adds no separate path that could leak it.</li></ul><h3 id="endpoints-confirmed-live" tabindex="-1">Endpoints, Confirmed Live <a class="header-anchor" href="#endpoints-confirmed-live" aria-label="Permalink to &quot;Endpoints, Confirmed Live&quot;">​</a></h3><p><a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a> verified both sources against the real pinned <code>pihole/pihole:2026.04.1</code> image with a real authenticated round trip, not just the self-served OpenAPI spec:</p><ul><li><code>pihole.status</code> sources from <code>GET /api/dns/blocking</code> (<code>{&quot;blocking&quot;: &quot;enabled&quot;|&quot;disabled&quot;|&quot;failed&quot;|&quot;unknown&quot;, &quot;timer&quot;: number|null}</code>) — mapped to this RFC&#39;s <code>reachable</code>/<code>blocking_enabled</code> result as: <code>&quot;enabled&quot;</code> → <code>true</code>, <code>&quot;disabled&quot;</code> → <code>false</code>, <code>&quot;failed&quot;</code>/<code>&quot;unknown&quot;</code> → <code>null</code> (never guessed). <strong>Confirmed security-relevant detail:</strong> <code>GET</code> and <code>POST /api/dns/blocking</code> are the <em>same URL</em> — POST is what changes blocking state. The implementation must be hard-restricted to GET only at the code level, not merely by intent.</li><li><code>pihole.summary</code> requires <strong>two</strong> real API calls, not one — a correction to this RFC&#39;s original assumption: the period-scoped <code>GET /api/stats/database/summary?from=&lt;unix&gt;&amp;until=&lt;unix&gt;</code> (returns <code>sum_queries</code>/<code>sum_blocked</code>/<code>percent_blocked</code>/<code>total_clients</code> for the requested window) supplies <code>queries_total</code>/<code>queries_blocked</code>/ <code>blocked_percentage</code>, while the live, unscoped <code>GET /api/stats/summary</code> supplies <code>blocklist_size</code> (<code>gravity.domains_being_blocked</code>) and <code>unique_clients</code> (<code>clients.active</code>, itself already a rolling 24-hour figure) — neither of which has a period-scoped equivalent in Pi-hole&#39;s own API. The <code>period</code> argument this RFC&#39;s schema declares is translated by the implementation into <code>from</code>/<code>until</code> Unix timestamps server-side; the model never sees or supplies raw timestamps.</li><li>Both confirmed-live responses contain only counts and percentages — empirically validating this RFC&#39;s aggregate-only, no-client-identity, no-domain-detail design, not merely asserting it. The research document also names the real, readily-available endpoints (<code>recent_blocked</code>, <code>top_clients</code>, <code>top_domains</code>) that would leak exactly what this RFC excludes, as evidence the exclusion is deliberate.</li><li>The observed error taxonomy (<code>unauthorized</code>, <code>rate_limiting</code>, <code>api_seats_exceeded</code>, <code>bad_request</code>, uniformly shaped as <code>{&quot;error&quot;: {&quot;key&quot;, &quot;message&quot;, &quot;hint&quot;}, &quot;took&quot;}</code>) maps directly onto RFC-0003&#39;s bounded-execution failure classification.</li></ul><p>All of this RFC&#39;s previously-open &quot;must still confirm&quot; items are now resolved by that research document; none remain blocking.</p><h2 id="interfaces-and-data-flow" tabindex="-1">Interfaces and Data Flow <a class="header-anchor" href="#interfaces-and-data-flow" aria-label="Permalink to &quot;Interfaces and Data Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model proposes pihole.summary({&quot;period&quot;: &quot;today&quot;})   [RFC-0004 flow]</span></span>
<span class="line"><span>    -&gt; RFC-0003 executor: resolve, validate arguments against the</span></span>
<span class="line"><span>       enumerated {&quot;today&quot;,&quot;last_24h&quot;} schema, check policy</span></span>
<span class="line"><span>       (automatic confirmation; read_only + local)</span></span>
<span class="line"><span>    -&gt; pihole.summary implementation:</span></span>
<span class="line"><span>        authenticate to Pi-hole&#39;s real API using the stored,</span></span>
<span class="line"><span>        capability-scoped credential (never exposed upstream)</span></span>
<span class="line"><span>        -&gt; aggregate counts only, shaped to the declared result_schema</span></span>
<span class="line"><span>    -&gt; result appended to model context, structured, per RFC-0004</span></span></code></pre></div><p>No path in this flow allows a per-domain or per-client field to reach the result — the schema itself is the enforcement point, not a convention the implementation is trusted to honor unchecked.</p><h2 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h2><ul><li>This is the most privacy-sensitive capability surface in the milestone: DNS query behavior across a household is close to browsing history. The aggregate-only boundary is deliberately stricter than what Pi-hole&#39;s own admin API can technically return, not merely as strict as it.</li><li>The credential-scoping requirement (capability-only access, never exposed to the model/Conversation Service) means even a fully successful prompt-injection attack against the model — per RFC-0004&#39;s untrusted-forever boundary, which already prevents this from executing anything unauthorized — could not additionally exfiltrate the Pi-hole credential itself, because nothing in the conversation path ever holds it.</li><li><code>blocking_enabled: null</code> (rather than a guessed default) when Pi-hole is unreachable avoids the specific failure mode of a capability fabricating a plausible-looking but false answer about the household&#39;s protection state.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h2><ul><li>Pi-hole unreachable: <code>pihole.status</code> returns <code>reachable: false, blocking_enabled: null</code> rather than failing the whole invocation — &quot;Pi-hole is down&quot; is itself a valid, useful answer, not an error state requiring the executor to reject the proposal.</li><li>Pi-hole reachable but the authenticated API call fails (auth failure, unexpected response shape): the capability implementation fails the invocation through RFC-0003&#39;s normal bounded-execution failure path, audited like any other capability failure — it does not fall back to guessing or to <code>console-health</code>&#39;s coarser TCP-only signal, which would blur two capabilities with different privacy postures together.</li><li>A response containing fields this RFC excludes is a capability implementation bug, not a runtime policy decision — the fix is correcting the implementation to match its declared <code>result_schema</code>, not adding a filter that could itself be forgotten or bypassed later.</li></ul><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and Migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and Migration&quot;">​</a></h2><p>No existing capability to migrate from. This RFC&#39;s only compatibility obligation is to the pinned Pi-hole version (<code>pihole/pihole:2026.04.1</code>, per <code>image-builder/sovereign/pihole-image.env</code>) and to <code>console-health</code>, which this RFC does not modify, replace, or depend on — both integrations may coexist indefinitely with genuinely different scopes.</p><h2 id="operations-and-observability" tabindex="-1">Operations and Observability <a class="header-anchor" href="#operations-and-observability" aria-label="Permalink to &quot;Operations and Observability&quot;">​</a></h2><ul><li><code>pihole.status</code>/<code>pihole.summary</code> invocations are audited exactly like any other capability per RFC-0003 — classification and outcome, never the household&#39;s actual query counts, in the durable log.</li><li>If Pi-hole&#39;s real API proves unreliable enough to affect capability availability in practice, that shows up as a normal failure rate in the existing audit log, not a separate monitoring surface this RFC needs to invent.</li></ul><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li>Contract-level tests against RFC-0003&#39;s registered schema: argument validation rejects any <code>period</code> value outside the enumerated set, and result validation rejects any field the schema doesn&#39;t declare (a direct test that the privacy boundary is structurally enforced, not just documented).</li><li>Fixture-backed tests for both capabilities&#39; happy path and the Pi-hole-unreachable path, without requiring live Pi-hole for every test run.</li><li>Once <code>pihole-api-assessment.md</code>&#39;s empirical questions are answered against the real device, integration tests against the real, pinned Pi-hole version, followed by real-hardware qualification per this project&#39;s standing practice of a dated report under <code>docs/research/</code>.</li><li>A specific adversarial test: request a result field outside the declared schema (simulating either an implementation bug or a malicious/compromised Pi-hole response) and confirm it is stripped or the invocation fails closed, never silently forwarded.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Reuse <code>console-health</code>&#39;s TCP-only check for <code>pihole.status</code> and stop there, deferring <code>pihole.summary</code> entirely.</strong> Considered, but rejected as incomplete: the milestone plan names &quot;summary&quot; capabilities explicitly, and the Exit Criteria requires &quot;at least three Pi-hole/ system questions invoke the correct read-only capability reliably&quot; — a single up/down check does not support three distinct real questions.</li><li><strong>Expose per-client query counts (not identities, just counts per device) as a middle ground.</strong> Rejected for this pass: even anonymized per-client counts can identify a specific household member&#39;s device by behavior pattern in a small household, which is exactly the kind of re-identification risk aggregate-only avoids. Revisit only as its own explicit, separately-reviewed decision if a real use case demands it — not as a default expansion of this RFC&#39;s scope.</li><li><strong>Let the model construct arbitrary Pi-hole API queries directly</strong> (a generic &quot;call this Pi-hole endpoint&quot; capability). Rejected outright: this would bypass RFC-0003&#39;s typed schema validation entirely and reintroduce exactly the &quot;arbitrary service access&quot; RFC-0002&#39;s Safety Boundary already forbids.</li></ul><h2 id="drawbacks-and-maintenance-cost" tabindex="-1">Drawbacks and Maintenance Cost <a class="header-anchor" href="#drawbacks-and-maintenance-cost" aria-label="Permalink to &quot;Drawbacks and Maintenance Cost&quot;">​</a></h2><ul><li>Aggregate-only scoping means some genuinely useful household questions (&quot;what got blocked on the kids&#39; tablet just now&quot;) are not answerable through this capability surface at all. This is an accepted, deliberate privacy tradeoff, not an oversight — see Alternatives Considered.</li><li>A second, capability-scoped Pi-hole credential (if the pinned version supports one) is an additional secret to provision, rotate, and include in the persistent-data backup/restore contract — real, ongoing operational surface area beyond <code>console-health</code>&#39;s credential-free TCP check.</li></ul><h2 id="unresolved-questions" tabindex="-1">Unresolved Questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved Questions&quot;">​</a></h2><p>Endpoint shapes, credential availability, and error/rate-limit behavior — this RFC&#39;s original open questions — are now resolved by <a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a> (Concluded 2026-08-09) and incorporated above. What remains is purely implementation-level:</p><ul><li>Exact <code>checked_at</code> timestamp precision/timezone handling.</li><li>Exact <code>webserver.api.max_sessions</code> default and whether it needs raising for Sovereign&#39;s own long-lived session to coexist with normal household web-UI use (named as an operational tuning question in the research document, not measured there).</li><li>Precise rate-limit thresholds (attempts per window) — documented as existing, not independently measured, to avoid locking out the real device&#39;s admin access during research.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li><code>pihole.status</code> and <code>pihole.summary</code> are registered against RFC-0003&#39;s contract with the schemas above, classified <code>read_only</code>/<code>local</code>/ <code>automatic</code>.</li><li>Result schema validation structurally rejects any field beyond what this RFC declares, verified by an adversarial test that attempts to return an excluded field (a client identity, a domain, a query timestamp) and confirms it never reaches the model or conversation context.</li><li>The Pi-hole credential these capabilities use is stored under <code>/data/sovereign/secrets</code>, is unreachable from the Conversation Service/model/Inference Provider Adapter, and is never present in any audit event.</li><li><code>pihole-api-assessment.md</code>&#39;s empirical questions (endpoint shape, credential scoping, rate-limit behavior) are answered against the real pinned Pi-hole version — done, see that document, Concluded 2026-08-09 — not merely assumed from general Pi-hole documentation.</li><li><code>pihole.summary</code>&#39;s implementation genuinely composes both confirmed endpoints (<code>database/summary</code> for period-scoped counts, <code>summary</code> for blocklist size and active-client count), not a single call this RFC originally assumed.</li><li><code>pihole.status</code> correctly reports <code>blocking_enabled: null</code> (not a guessed default) when Pi-hole is unreachable, verified against a real stopped/unreachable Pi-hole on real hardware.</li><li>The milestone&#39;s Exit Criteria bar — at least three Pi-hole/system questions reliably invoking the correct read-only capability against a versioned evaluation corpus — is met using <code>system.health</code> (RFC-0002), <code>pihole.status</code>, and <code>pihole.summary</code> together.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Accepted (2026-08-09, project creator).</strong> <code>pihole.status</code> and <code>pihole.summary</code>, their schemas, aggregate-only privacy boundary, and credential-handling requirements, are accepted, incorporating the real, live-verified findings from <a href="./../research/pihole-api-assessment.html">docs/research/pihole-api-assessment.md</a>.</p><p><strong>Implementation update (2026-08-09):</strong> both capabilities are implemented (<code>sovereign_capabilities.py</code>, <code>sovereign_pihole.py</code>), unit-tested against mocked HTTP responses, and additionally smoke-tested against the real device outside those mocks with no discrepancy found — see the <a href="./../research/pihole-capabilities-smoke-test-report.html">pihole capabilities smoke test report</a>. Full hardware qualification remains pending a real caller (the Conversation Service, RFC-0002, not yet built).</p>`,52)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
